#!/usr/bin/env python3
"""Read-only independent arithmetic review. Uses installed TypeScript; no app/test/config edits.
Run from any directory: python3 output/release-review/data/reproduce-calculations.py
Writes only a new independent-reproduced.json beside this helper; intermediate modules/arrays use tempfile.
"""
from pathlib import Path
import tempfile,subprocess,json,shutil
root=Path(__file__).resolve().parents[3]
generate="from datetime import date,timedelta\nimport json,random\nfrom pathlib import Path\nP=Path('/home/cameron/Projects/feie_tool/output/release-review/data')\ncases=[]\ndef add(name,year,ranges): cases.append(dict(name=name,year=year,ranges=ranges))\nadd('earliest-nonleap',2024,[['2023-01-02','2023-11-27']])\nadd('earliest-leap',2025,[['2024-01-02','2024-11-26']])\nadd('zero-overlap',2024,[['2025-02-05','2025-12-31']])\nadd('latest-start',2025,[['2025-12-31','2026-11-25']])\nadd('latest-start-only',2025,[['2026-02-04','2026-12-30']])\nadd('regulation-travel-example',1983,[['1982-03-07','1982-06-24'],['1982-07-25','1983-08-21'],['1983-09-06','1983-12-31']])\nfor n in [329,330]: add(f'threshold-{n}',2025,[['2025-01-01',(date(2025,1,1)+timedelta(days=n-1)).isoformat()]])\nadd('multiple-overlap',2024,[['2023-01-01','2024-05-31'],['2024-08-01','2025-12-31']])\nadd('multiple-disjoint',2024,[['2023-01-01','2024-03-31'],['2024-10-01','2025-12-31']])\nadd('leap-sensitivity',2024,[['2024-02-29','2025-01-22'],['2025-02-28','2025-02-28']])\nadd('duplicate-raw-occupancy',2025,[['2025-01-01','2025-11-26'],['2025-01-01','2025-11-26']])\nadd('ordinary-fully-recorded',2025,[['2025-01-01','2025-12-31']])\nadd('partial-midyear',2025,[['2025-07-01','2026-05-26']])\nrng=random.Random(911)\nfor year in [1901,1904,1999,2000,2023,2024,2025,2096,2099]:\n for density in [0,.25,.88,.9,.92,.97,1]:\n  days=[]; d=date(year-1,1,1)\n  while d<=date(year+1,12,31):\n   if rng.random()<density:days.append(d.isoformat())\n   d+=timedelta(days=1)\n  add(f'random-{year}-{density}',year,[[d,d] for d in days])\nP.joinpath('oracle-inputs.json').write_text(json.dumps(cases,indent=2))\n"
compare='actual=json.loads(P.joinpath(\'oracle-actual.json\').read_text())\nsummary=[]\ndef days(a,b):\n d=a\n while d<=b:\n  yield d\n  d+=timedelta(days=1)\nfor c in actual:\n y=c[\'year\']; ys=date(y,1,1); ye=date(y,12,31)\n foreign=set()\n for a,b in c[\'ranges\']:foreign.update(days(date.fromisoformat(a),date.fromisoformat(b)))\n allwindows=[]; covered=set(); passing=0; maxforeign=0\n for s in days(date(y-1,1,1),ye):\n  if s.month==2 and s.day==29:continue\n  e=date(s.year+1,s.month,s.day)-timedelta(days=1)\n  if e<ys:continue\n  f=sum(d in foreign for d in days(s,e));maxforeign=max(maxforeign,f)\n  allwindows.append([s.isoformat(),e.isoformat(),f])\n  if f>=330:\n   passing+=1;covered.update(days(max(s,ys),min(e,ye)))\n denominator=(ye-ys).days+1\n a=c[\'actual\'];issues=[]\n for key,want in [(\'days\',len(covered)),(\'denominator\',denominator),(\'passing\',passing),(\'maxForeign\',maxforeign),(\'ordinaryCandidates\',allwindows)]:\n  if a[key]!=want:issues.append(key)\n supportdays=set()\n for w in a[\'support\']:\n  s=date.fromisoformat(w[\'window_start\']);e=date.fromisoformat(w[\'window_end\'])\n  if sum(d in foreign for d in days(s,e))<330:issues.append(\'invalid-support\')\n  supportdays.update(days(max(s,ys),min(e,ye)))\n if covered!=supportdays:issues.append(\'support-union\')\n if a[\'fraction\']!=len(covered)/denominator:issues.append(\'fraction\')\n summary.append(dict(name=c[\'name\'],year=y,input_ranges=c[\'ranges\'] if not c[\'name\'].startswith(\'random-\') else f"seed 911; {len(foreign)} daily foreign records",expected_days=len(covered),actual_days=a[\'days\'],denominator=denominator,passing=passing,max_foreign=maxforeign,candidate_count=len(allwindows),support=a[\'support\'],coverage=a[\'coverage\'],leap=a.get(\'leap\'),mismatches=issues))\nP.joinpath(\'independent-calculation-results.json\').write_text(json.dumps(dict(seed=911,cases=len(summary),mismatches=sum(bool(s[\'mismatches\']) for s in summary),results=summary),indent=2))\n'
js="import fs from 'node:fs';\nimport path from 'node:path';\nimport ts from '/home/cameron/Projects/feie_tool/node_modules/typescript/lib/typescript.js';\nconst root='/home/cameron/Projects/feie_tool';\nconst out='/tmp/feie-review-modules';\nfor (const folder of ['domain','services']) {\n fs.mkdirSync(`${out}/${folder}`,{recursive:true});\n for (const file of fs.readdirSync(`${root}/src/${folder}`)) {\n  if (!file.endsWith('.ts') || file==='report.ts' || file==='reportPdf.ts') continue;\n  const source=fs.readFileSync(`${root}/src/${folder}/${file}`,'utf8');\n  let js=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ES2022}}).outputText;\n  js=js.replace(/from '(\\.\\.?\\/[^']+)'/g,(_,p)=>`from '${p}.mjs'`);\n  fs.writeFileSync(`${out}/${folder}/${file.replace('.ts','.mjs')}`,js);\n }\n}\nconst {evaluateFeie,enumerateWindows}=await import(`${out}/domain/feie.mjs`);\nconst {assessTravel}=await import(`${out}/services/travelCalculator.mjs`);\nconst {calculateFeie}=await import(`${out}/services/calculator.mjs`);\nconst cases=JSON.parse(fs.readFileSync(`${root}/output/release-review/data/oracle-inputs.json`));\nconst results=cases.map(c=>{\n const input={taxYearStart:`${c.year}-01-01`,taxYearEnd:`${c.year}-12-31`,taxYearDays:0,foreignPeriods:c.ranges.map(([start_date,end_date])=>({start_date,end_date})),usPeriods:[]};\n const r=evaluateFeie(input);\n return {...c,actual:{days:r.qualifyingDays,denominator:r.totalTaxYearDays,fraction:r.coverageFraction,passing:r.qualifyingWindowCount,maxForeign:r.maxForeignDays,coverage:r.qualifyingCoverage,support:r.supportingWindows,ordinaryCandidates:enumerateWindows(input).map(w=>[w.window_start,w.window_end,w.foreign_days]),leap:r.leapDayReview}};\n});\nfs.writeFileSync(`${root}/output/release-review/data/oracle-actual.json`,JSON.stringify(results,null,2));\n"
with tempfile.TemporaryDirectory(prefix='feie-independent-') as work:
    scope={}
    generate=generate.replace("P=Path('/home/cameron/Projects/feie_tool/output/release-review/data')", "P=Path("+repr(work)+")")
    exec(generate,scope)
    js=js.replace('/home/cameron/Projects/feie_tool',str(root))
    js=js.replace("const out='/tmp/feie-review-modules';", "const out="+json.dumps(work+'/modules')+";\nconst work="+json.dumps(work)+";")
    js=js.replace('${root}/output/release-review/data','${work}')
    runner=Path(work)/'actual.mjs';runner.write_text(js)
    subprocess.run(['node',str(runner)],check=True)
    exec(compare,scope)
    result=json.loads((Path(work)/'independent-calculation-results.json').read_text())
    target=Path(__file__).with_name('independent-reproduced.json')
    target.write_text(json.dumps(result,indent=2))
    print(json.dumps({'cases':result['cases'],'mismatches':result['mismatches'],'output':str(target)}))
    if result['mismatches']:raise SystemExit(1)
